text:
panel-list {
  --panel-list-background-color: var(--color-surface-subtle);
  --panel-list-color: var(--color-text-base);
  --panel-list-border-color: var(--color-surface-border);
  --panel-list-border-radius: 8px;
  padding: 4px;
}

panel-item::part(button) {
  border-radius: 3px;
  background-position-x: 3px;
  --button-background-color-hover: var(--button-hover-background-color);
  --button-background-color-active: var(--button-active-background-color);
}

panel-item[action="remove"]::part(button) {
  background-image: var(--icon-trash);
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;
}
